// Narrow compile-time projection of the Herdr 0.1.13 declarations used by the
// native mods. Keep signatures aligned with the installed gpui-kit.d.ts and
// herdr.d.ts; runtime files are generated by Herdr and are not vendored here.
declare module "gpui-kit" {
  export type Element = NativeElement;
  export type Props = Record<string, unknown>;

  export interface Entity {
    set_props(props?: Props): void;
    release(): boolean;
  }

  export interface Task {
    cancel(): void;
    is_done(): boolean;
  }

  export interface FocusHandle {
    focus(): void;
    is_focused(): boolean;
    release(): boolean;
  }

  export interface KeyEvent {
    key: string;
    keystroke: string;
    key_char?: string;
    modifiers: { shift: boolean; control: boolean; alt: boolean; platform: boolean };
    is_held?: boolean;
  }

  export interface InputEvent {
    readonly secondary?: boolean;
    readonly shift?: boolean;
  }

  export interface Context {
    notify(target?: Entity): void;
    stop_propagation(): void;
    focus_handle(): FocusHandle;
    spawn(body: (cx: AsyncContext) => unknown): Task;
  }

  export interface AsyncContext extends Context {}

  export interface NativeElement {
    child(child: NativeElement | Entity | string | number | boolean): this;
    children(children: Iterable<NativeElement | Entity | string | number | boolean>): this;
    id(name: string): this;
    bg(color: string): this;
    border_1(): this;
    border_color(color: string): this;
    flex_1(): this;
    font_semibold(): this;
    gap(value: number): this;
    h(value: number): this;
    hover(declare: (element: NativeElement) => NativeElement | void): this;
    items_center(): this;
    justify_between(): this;
    max_h(value: number): this;
    min_h(value: number): this;
    on_item_click(handler: (key: string, cx: Context) => void): this;
    on_key_down(handler: (event: KeyEvent, cx: Context) => void): this;
    p(value: number): this;
    px(value: number): this;
    py(value: number): this;
    rounded(value: number): this;
    text_color(color: string): this;
    text_size(value: number): this;
    track_focus(handle: FocusHandle): this;
    track_scroll(handle: import("gpui-base").VirtualListScrollHandle): this;
    w(value: number): this;
    cursor_pointer(): this;
  }

  export abstract class View {
    constructor(props?: Props);
    init?(props: Props | undefined, cx: AsyncContext): void;
    abstract render(cx: Context): Element | Entity | string;
  }

  export function div(): NativeElement;
}

declare module "gpui-base" {
  import type { Context, NativeElement } from "gpui-kit";

  export interface ItemRange {
    start: number;
    end: number;
  }

  export interface InputState {
    value(): string;
    on(event: "change" | "submit", handler: (event: import("gpui-kit").InputEvent, cx: Context) => void): boolean;
    focus(): void;
    release(): boolean;
  }

  export interface VirtualListScrollHandle {
    scroll_to_item(index: number, strategy?: "top" | "center"): void;
    scroll_to_bottom(): void;
    release(): boolean;
  }

  export const InputState: {
    new: (options?: { placeholder?: string; value?: string }) => InputState;
  };
  export const Input: {
    new: (state: InputState) => NativeElement;
  };
  export const VirtualListScrollHandle: {
    new: () => VirtualListScrollHandle;
  };

  export function h_flex(): NativeElement;
  export function v_flex(): NativeElement;
  export function v_virtual_list(
    id: string | number,
    itemCount: number,
    itemSizes: number | number[],
    getKey: (index: number) => string,
    render: (range: ItemRange, cx: Context) => NativeElement[],
  ): NativeElement;
}

declare module "herdr" {
  export interface ExecResult {
    code: number;
    stdout: string;
    stderr: string;
  }

  export interface SpaceReference {
    id: string;
    name: string;
    tabs: { id: string; name: string; active: boolean; zoomed: boolean; panes: number }[];
    folder: string;
    machine: string | null;
    active: boolean;
  }

  export interface ModProps {
    overlay?: string;
  }

  export function appHome(): string;
  export function home(): string;
  export function readTextFile(path: string): Promise<string | null>;
  export function exec(
    command: string,
    args?: string[],
    options?: { cwd?: string; on?: string | null },
  ): Promise<ExecResult>;
  export function spaces(): SpaceReference[];
  export function panes(): {
    pane: string;
    terminal: string | null;
    mod?: string;
    tab: string;
    zoomed: boolean;
  }[];
  export function focused(): {
    space: string;
    tab: string;
    pane: string | null;
    terminal: string | null;
    shown: string | null;
  } | null;
  export function run(name: string, args?: Record<string, unknown>): null;
  export function closeOverlay(id: string): null;
  export function props(): ModProps;
  export function shared(key: string): unknown;
  export function setShared(key: string, value: unknown): null;
  export function nextCommand(): Promise<string>;
  export function notify(message: {
    title: string;
    body?: string;
    level?: "info" | "success" | "warning" | "error";
  }): string;
  export function theme(): Record<string, string>;
}
